import hashlib, re
from datasketch import MinHash, MinHashLSH

def shingles(text: str, n: int = 5) -> set[str]:
    w = re.findall(r"\w+", text.lower())
    return {" ".join(w[i:i + n]) for i in range(max(1, len(w) - n + 1))}

def minhash(text: str) -> MinHash:
    m = MinHash(num_perm=128)
    for s in shingles(text):
        m.update(s.encode())
    return m

def gopher_like(t: str) -> bool:
    words = t.split()
    symbols = t.count("#") + t.count("...")
    return 50 <= len(words) <= 100_000 and symbols / max(len(words), 1) < 0.1

eval_grams = {g for doc in eval_set for g in shingles(doc, n=13)}  # decontamination
lsh, seen, kept = MinHashLSH(threshold=0.8, num_perm=128), set(), []

for i, doc in enumerate(corpus):
    h = hashlib.sha1(" ".join(doc.lower().split()).encode()).hexdigest()
    if h in seen or not gopher_like(doc):
        continue                                    # exact duplicate or junk
    if shingles(doc, n=13) & eval_grams:
        continue                                    # leaks an eval item
    m = minhash(doc)
    if lsh.query(m):
        continue                                    # near-duplicate of a kept doc
    seen.add(h); lsh.insert(str(i), m); kept.append(doc)

kept = [d for d in kept if quality_score(d) >= 3]   # FineWeb-Edu-style classifier, 0-5
